window.BOOK={"key":"isaghuji","app":"mutoon","lsk":"mutoon_isaghuji_v1","title":"إيساغوجي","unitWord":"فقرة","sub":"متن إيساغوجي في المنطق · أثير الدين الأبهري (ت ٦٦٣هـ) · ٨ بابًا","source":"https://ar.wikisource.org/wiki/متن_إيساغوجي (متن إيساغوجي المشكول = نص المكتبة الشاملة الذهبية، ketabonline 102532، وهو النص الذي يقرأ منه الحازمي في «شرح المطلع») · قوبل بـ: مغني الطلاب شرح متن إيساغوجي لمحمود المغنيسي (ويكي مصدر، متن الشرح المشكول بين الأقواس) + شرح المطلع للحازمي (ketabonline 4128، المتن المقروء المشكول) + تهذيب فن المنطق لمحمد صبحي العايدي (ketabonline 42172) — مقابلة آلية كلمة كلمة؛ انظر isaghuji-sources.md","note":"النص المشكول المتداول (ويكي مصدر/الشاملة الذهبية، وهو ما يقرأ منه الحازمي في شرح المطلع)، قوبل آليًّا كلمةً كلمة بمتن «مغني الطلاب» للمغنيسي وبالمتن المقروء في شرح الحازمي وبمتن «تهذيب فن المنطق» للعايدي. وأُكمل سقطٌ ظاهر في القياس الاستثنائي من «مغني الطلاب»، وصُحّح الشكل أو كُمّل في ٢٥٧ موضعًا (أكثرها سكون لام التعريف ورسم «لا» و«هذا»)، وكل ذلك مسجّل في تقرير المصادر.","chapters":[{"id":"is1","title":"مُقَدِّمَةُ الْمَتْنِ","units":[{"id":"is1_1","label":"مُقَدِّمَةُ الْمَتْنِ · ١","segs":[["matn","قَالَ الشَّيْخُ الْإِمَامُ أَفْضَلُ الْمُتَأَخِّرِينَ، قُدْوَةُ الْحُكَمَاءِ الرَّاسِخِينَ أَثِيرُ الدِّينِ الْأَبْهَرِيُّ، طَيَّبَ اللهُ ثَرَاهُ، وَجَعَلَ الْجَنَّةَ مَثْوَاهُ:"]]},{"id":"is1_2","label":"مُقَدِّمَةُ الْمَتْنِ · ٢","segs":[["matn","نَحْمَدُ اللهَ تَعَالَى عَلَى تَوْفِيقِهِ، وَنَسْأَلُهُ هِدَايَةَ طَرِيقِهِ، وَنُصَلِّي عَلَى مُحَمَّدٍ وَعَلَى عِتْرَتِهِ أَجْمَعِينَ."]]},{"id":"is1_3","label":"مُقَدِّمَةُ الْمَتْنِ · ٣","segs":[["matn","وَبَعْدُ: فَهَذِهِ رِسَالَةٌ فِي الْمَنْطِقِ، أَوْرَدْنَا فِيهَا مَا يَجِبُ اسْتِحْضَارُهُ لِمَنْ يَبْتَدِئُ فِي شَيْءٍ مِنَ الْعُلُومِ، مُسْتَعِينًا بِاللهِ تَعَالَى، إِنَّهُ مُفِيضُ الْخَيْرِ وَالْجُودِ."]]}]},{"id":"is2","title":"إِيسَاغُوجِي","units":[{"id":"is2_1","label":"إِيسَاغُوجِي · ١","segs":[["matn","اللَّفْظُ الدَّالُّ يَدُلُّ عَلَى تَمَامِ مَا وُضِعَ لَهُ بِالْمُطَابَقَةِ، وَعَلَى جُزْئِهِ بِالتَّضَمُّنِ إِنْ كَانَ لَهُ جُزْءٌ، وَعَلَى مَا يُلَازِمُهُ فِي الذِّهْنِ بِالِالْتِزَامِ."]]},{"id":"is2_2","label":"إِيسَاغُوجِي · ٢","segs":[["matn","كَالْإِنْسَانِ: فَإِنَّهُ يَدُلُّ عَلَى الْحَيَوَانِ النَّاطِقِ بِالْمُطَابَقَةِ، وَعَلَى أَحَدِهِمَا بِالتَّضَمُّنِ، وَعَلَى قَابِلِ الْعِلْمِ وَصِنَاعَةِ الْكِتَابَةِ بِالِالْتِزَامِ."]]},{"id":"is2_3","label":"إِيسَاغُوجِي · ٣","segs":[["matn","ثُمَّ اللَّفْظُ: إِمَّا مُفْرَدٌ: وَهُوَ الَّذِي لَا يُرَادُ بِالْجُزْءِ مِنْهُ دِلَالَةٌ عَلَى جُزْءِ مَعْنَاهُ، كَالْإِنْسَانِ. وَإِمَّا مُؤَلَّفٌ: وَهُوَ الَّذِي لَا يَكُونُ كَذَلِكَ، كَرَامِي الْحِجَارَةِ."]]},{"id":"is2_4","label":"إِيسَاغُوجِي · ٤","segs":[["matn","وَالْمُفْرَدُ: إِمَّا كُلِّيٌّ: وَهُوَ الَّذِي لَا يَمْنَعُ نَفْسُ تَصَوُّرِ مَفْهُومِهِ مِنْ وُقُوعِ الشَّرِكَةِ فِيهِ، كَالْإِنْسَانِ."]]},{"id":"is2_5","label":"إِيسَاغُوجِي · ٥","segs":[["matn","وَإِمَّا جُزْئِيٌّ: وَهُوَ الَّذِي يَمْنَعُ نَفْسُ تَصَوُّرِ مَفْهُومِهِ مِنْ ذَلِكَ، كَزَيْدٍ عَلَمًا."]]},{"id":"is2_6","label":"إِيسَاغُوجِي · ٦","segs":[["matn","وَالْكُلِّيُّ: إِمَّا ذَاتِيٌّ: وَهُوَ الَّذِي يَدْخُلُ فِي حَقِيقَةِ جُزْئِيَّاتِهِ، كَالْحَيَوَانِ بِالنِّسْبَةِ إِلَى الْإِنْسَانِ وَالْفَرَسِ. وَإِمَّا عَرَضِيٌّ: وَهُوَ الَّذِي يُخَالِفُهُ، كَالضَّاحِكِ بِالنِّسْبَةِ إِلَى الْإِنْسَانِ."]]},{"id":"is2_7","label":"إِيسَاغُوجِي · ٧","segs":[["matn","وَالذَّاتِيُّ: إِمَّا مَقُولٌ فِي جَوَابِ مَا هُوَ بِحَسَبِ الشَّرِكَةِ الْمَحْضَةِ، كَالْحَيَوَانِ بِالنِّسْبَةِ إِلَى الْإِنْسَانِ وَالْفَرَسِ، وَهُوَ الْجِنْسُ."]]},{"id":"is2_8","label":"إِيسَاغُوجِي · ٨","segs":[["matn","وَيُرْسَمُ بِأَنَّهُ كُلِّيٌّ مَقُولٌ عَلَى كَثِيرِينَ مُخْتَلِفِينَ بِالْحَقَائِقِ فِي جَوَابِ مَا هُوَ."]]},{"id":"is2_9","label":"إِيسَاغُوجِي · ٩","segs":[["matn","وَإِمَّا مَقُولٌ فِي جَوَابِ مَا هُوَ بِحَسَبِ الشَّرِكَةِ وَالْخُصُوصِيَّةِ مَعًا، كَالْإِنْسَانِ بِالنِّسْبَةِ إِلَى أَفْرَادِهِ نَحْوُ زَيْدٍ وَعَمْرٍو، وَهُوَ النَّوْعُ."]]},{"id":"is2_10","label":"إِيسَاغُوجِي · ١٠","segs":[["matn","وَيُرْسَمُ بِأَنَّهُ كُلِّيٌّ مَقُولٌ عَلَى كَثِيرِينَ مُخْتَلِفِينَ بِالْعَدَدِ دُونَ الْحَقِيقَةِ فِي جَوَابِ مَا هُوَ."]]},{"id":"is2_11","label":"إِيسَاغُوجِي · ١١","segs":[["matn","وَإِمَّا غَيْرُ مَقُولٍ فِي جَوَابِ مَا هُوَ، بَلْ مَقُولٌ فِي جَوَابِ أَيُّ شَيْءٍ هُوَ فِي ذَاتِهِ، وَهُوَ الَّذِي يُمَيِّزُ الشَّيْءَ عَمَّا يُشَارِكُهُ فِي الْجِنْسِ، كَالنَّاطِقِ بِالنِّسْبَةِ إِلَى الْإِنْسَانِ، وَهُوَ الْفَصْلُ."]]},{"id":"is2_12","label":"إِيسَاغُوجِي · ١٢","segs":[["matn","وَيُرْسَمُ بِأَنَّهُ كُلِّيٌّ يُقَالُ عَلَى الشَّيْءِ فِي جَوَابِ أَيُّ شَيْءٍ هُوَ فِي ذَاتِهِ."]]},{"id":"is2_13","label":"إِيسَاغُوجِي · ١٣","segs":[["matn","وَأَمَّا الْعَرَضِيُّ: فَإِمَّا أَنْ يَمْتَنِعَ انْفِكَاكُهُ عَنِ الْمَاهِيَّةِ، وَهُوَ الْعَرَضُ اللَّازِمُ، أَوْ لَا يَمْتَنِعَ، وَهُوَ الْعَرَضُ الْمُفَارِقُ."]]},{"id":"is2_14","label":"إِيسَاغُوجِي · ١٤","segs":[["matn","وَكُلُّ وَاحِدٍ مِنْهُمَا إِمَّا أَنْ يَخْتَصَّ بِحَقِيقَةٍ وَاحِدَةٍ، وَهُوَ الْخَاصَّةُ، كَالضَّاحِكِ بِالْقُوَّةِ وَبِالْفِعْلِ لِلْإِنْسَانِ."]]},{"id":"is2_15","label":"إِيسَاغُوجِي · ١٥","segs":[["matn","وَتُرْسَمُ بِأَنَّهَا كُلِّيَّةٌ تُقَالُ عَلَى مَا تَحْتَ حَقِيقَةٍ وَاحِدَةٍ فَقَطْ قَوْلًا عَرَضِيًّا."]]},{"id":"is2_16","label":"إِيسَاغُوجِي · ١٦","segs":[["matn","وَإِمَّا أَنْ يَعُمَّ حَقَائِقَ فَوْقَ وَاحِدَةٍ، وَهْوَ الْعَرَضُ الْعَامُّ، كَالْمُتَنَفِّسِ بِالْقُوَّةِ وَالْفِعْلِ بِالنِّسْبَةِ لِلْإِنْسَانِ وَغَيْرِهِ مِنَ الْحَيَوَانَاتِ."]]},{"id":"is2_17","label":"إِيسَاغُوجِي · ١٧","segs":[["matn","وَيُرْسَمُ بِأَنَّهُ كُلِّيٌّ يُقَالُ عَلَى مَا تَحْتَ حَقَائِقَ مُخْتَلِفَةٍ قَوْلًا عَرَضِيًّا."]]}]},{"id":"is3","title":"الْقَوْلُ الشَّارِحُ","units":[{"id":"is3_1","label":"الْقَوْلُ الشَّارِحُ · ١","segs":[["matn","الْحَدُّ: قَوْلٌ دَالٌّ عَلَى مَاهِيَّةِ الشَّيْءِ، وَهْوَ الَّذِي يَتَرَكَّبُ مِنْ جِنْسِ الشَّيْءِ وَفَصْلِهِ الْقَرِيبَيْنِ، كَالْحَيَوَانِ النَّاطِقِ بِالنِّسْبَةِ إِلَى الْإِنْسَانِ، وَهْوَ الْحَدُّ التَّامُّ."]]},{"id":"is3_2","label":"الْقَوْلُ الشَّارِحُ · ٢","segs":[["matn","وَالْحَدُّ النَّاقِصُ: وَهْوَ الَّذِي يَتَرَكَّبُ مِنْ جِنْسِ الشَّيْءِ الْبَعِيدِ وَفَصْلِهِ الْقَرِيبِ، كَالْجِسْمِ النَّاطِقِ بِالنِّسْبَةِ إِلَى الْإِنْسَانِ."]]},{"id":"is3_3","label":"الْقَوْلُ الشَّارِحُ · ٣","segs":[["matn","وَالرَّسْمُ التَّامُّ: وَهْوَ الَّذِي يَتَرَكَّبُ مِنْ جِنْسِ الشَّيْءِ الْقَرِيبِ وَخَوَاصِّهِ اللَّازِمَةِ لَهُ، كَالْحَيَوَانِ الضَّاحِكِ فِي تَعْرِيفِ الْإِنْسَانِ."]]},{"id":"is3_4","label":"الْقَوْلُ الشَّارِحُ · ٤","segs":[["matn","وَالرَّسْمُ النَّاقِصُ: وَهْوَ الَّذِي يَتَرَكَّبُ مِنْ عَرَضِيَّاتٍ تَخْتَصُّ جُمْلَتُهَا بِحَقِيقَةٍ وَاحِدَةٍ، كَقَوْلِنَا فِي تَعْرِيفِ الْإِنْسَانِ: إِنَّهُ مَاشٍ عَلَى قَدَمَيْهِ، عَرِيضُ الْأَظْفَارِ، بَادِي الْبَشَرَةِ، مُسْتَقِيمُ الْقَامَةِ، ضَحَّاكٌ بِالطَّبْعِ."]]}]},{"id":"is4","title":"الْقَضَايَا","units":[{"id":"is4_1","label":"الْقَضَايَا · ١","segs":[["matn","الْقَضِيَّةُ: قَوْلٌ يَصِحُّ أَنْ يُقَالَ لِقَائِلِهِ: إِنَّهُ صَادِقٌ فِيهِ أَوْ كَاذِبٌ."]]},{"id":"is4_2","label":"الْقَضَايَا · ٢","segs":[["matn","وَهِيَ إِمَّا حَمْلِيَّةٌ، كَقَوْلِنَا: زَيْدٌ كَاتِبٌ. وَإِمَّا شَرْطِيَّةٌ مُتَّصِلَةٌ، كَقَوْلِنَا: إِنْ كَانَتِ الشَّمْسُ طَالِعَةً فَالنَّهَارُ مَوْجُودٌ."]]},{"id":"is4_3","label":"الْقَضَايَا · ٣","segs":[["matn","وَإِمَّا شَرْطِيَّةٌ مُنْفَصِلَةٌ، كَقَوْلِنَا: الْعَدَدُ إِمَّا أَنْ يَكُونَ زَوْجًا أَوْ فَرْدًا."]]},{"id":"is4_4","label":"الْقَضَايَا · ٤","segs":[["matn","وَالْجُزْءُ الْأَوَّلُ مِنَ الْحَمْلِيَّةِ يُسَمَّى مَوْضُوعًا، وَالثَّانِي مَحْمُولًا. وَالْجُزْءُ الْأَوَّلُ مِنَ الشَّرْطِيَّةِ يُسَمَّى مُقَدَّمًا، وَالثَّانِي تَالِيًا."]]},{"id":"is4_5","label":"الْقَضَايَا · ٥","segs":[["matn","وَالْقَضِيَّةُ: إِمَّا مُوجَبَةٌ، كَقَوْلِنَا: زَيْدٌ كَاتِبٌ. وَإِمَّا سَالِبَةٌ، كَقَوْلِنَا: زَيْدٌ لَيْسَ بِكَاتِبٍ."]]},{"id":"is4_6","label":"الْقَضَايَا · ٦","segs":[["matn","وَكُلُّ وَاحِدَةٍ مِنْهُمَا: إِمَّا مَخْصُوصَةٌ كَمَا ذَكَرْنَا، وَإِمَّا كُلِّيَّةٌ مُسَوَّرَةٌ، كَقَوْلِنَا: كُلُّ إِنْسَانٍ كَاتِبٌ، وَلَا شَيْءَ مِنَ الْإِنْسَانِ بِكَاتِبٍ."]]},{"id":"is4_7","label":"الْقَضَايَا · ٧","segs":[["matn","وَإِمَّا جُزْئِيَّةٌ مُسَوَّرَةٌ، كَقَوْلِنَا: بَعْضُ الْإِنْسَانِ كَاتِبٌ، وَبَعْضُ الْإِنْسَانِ لَيْسَ بِكَاتِبٍ."]]},{"id":"is4_8","label":"الْقَضَايَا · ٨","segs":[["matn","وَإِمَّا أَنْ لَا يَكُونَ كَذَلِكَ، وَتُسَمَّى مُهْمَلَةً، كَقَوْلِنَا: الْإِنْسَانُ كَاتِبٌ، وَالْإِنْسَانُ لَيْسَ بِكَاتِبٍ."]]},{"id":"is4_9","label":"الْقَضَايَا · ٩","segs":[["matn","وَالْمُتَّصِلَةُ: إِمَّا لُزُومِيَّةٌ، كَقَوْلِنَا: إِنْ كَانَتِ الشَّمْسُ طَالِعَةً فَالنَّهَارُ مَوْجُودٌ. وَإِمَّا اتِّفَاقِيَّةٌ، كَقَوْلِنَا: إِنْ كَانَ الْإِنْسَانُ نَاطِقًا فَالْحِمَارُ نَاهِقٌ."]]},{"id":"is4_10","label":"الْقَضَايَا · ١٠","segs":[["matn","وَالْمُنْفَصِلَةُ: إِمَّا حَقِيقِيَّةٌ، كَقَوْلِنَا: الْعَدَدُ إِمَّا زَوْجٌ وَإِمَّا فَرْدٌ، وَهِيَ إِمَّا مَانِعَةُ الْجَمْعِ وَالْخُلُوِّ مَعًا كَمَا ذَكَرْنَا."]]},{"id":"is4_11","label":"الْقَضَايَا · ١١","segs":[["matn","وَإِمَّا مَانِعَةُ الْجَمْعِ فَقَطْ، كَقَوْلِنَا: هَذَا الشَّيْءُ إِمَّا أَنْ يَكُونَ شَجَرًا أَوْ حَجَرًا."]]},{"id":"is4_12","label":"الْقَضَايَا · ١٢","segs":[["matn","وَإِمَّا مَانِعَةُ الْخُلُوِّ فَقَطْ، كَقَوْلِنَا: زَيْدٌ إِمَّا أَنْ يَكُونَ فِي الْبَحْرِ، وَإِمَّا أَنْ لَا يَغْرَقَ."]]},{"id":"is4_13","label":"الْقَضَايَا · ١٣","segs":[["matn","وَقَدْ تَكُونُ الْمُنْفَصِلَاتُ ذَوَاتِ أَجْزَاءٍ، كَقَوْلِنَا: الْعَدَدُ إِمَّا زَائِدٌ أَوْ نَاقِصٌ أَوْ مُسَاوٍ."]]}]},{"id":"is5","title":"التَّنَاقُضُ","units":[{"id":"is5_1","label":"التَّنَاقُضُ · ١","segs":[["matn","هُوَ اخْتِلَافُ الْقَضِيَّتَيْنِ بِالْإِيجَابِ وَالسَّلْبِ، بِحَيْثُ يَقْتَضِي لِذَاتِهِ أَنْ تَكُونَ إِحْدَاهُمَا صَادِقَةً وَالْأُخْرَى كَاذِبَةً، كَقَوْلِنَا: زَيْدٌ كَاتِبٌ، زَيْدٌ لَيْسَ بِكَاتِبٍ."]]},{"id":"is5_2","label":"التَّنَاقُضُ · ٢","segs":[["matn","وَلَا يَتَحَقَّقُ ذَلِكَ إِلَّا بَعْدَ اتِّفَاقِهِمَا فِي الْمَوْضُوعِ، وَالْمَحْمُولِ، وَالزَّمَانِ، وَالْمَكَانِ، وَالْإِضَافَةِ، وَالْقُوَّةِ، وَالْفِعْلِ، وَالْجُزْءِ، وَالْكُلِّ، وَالشَّرْطِ، نَحْوُ: زَيْدٌ كَاتِبٌ، زَيْدٌ لَيْسَ بِكَاتِبٍ."]]},{"id":"is5_3","label":"التَّنَاقُضُ · ٣","segs":[["matn","فَنَقِيضُ الْمُوجَبَةِ الْكُلِّيَّةِ إِنَّمَا هِيَ السَّالِبَةُ الْجُزْئِيَّةُ، كَقَوْلِنَا: كُلُّ إِنْسَانٍ حَيَوَانٌ، وَبَعْضُ الْإِنْسَانِ لَيْسَ بِحَيَوَانٍ."]]},{"id":"is5_4","label":"التَّنَاقُضُ · ٤","segs":[["matn","وَنَقِيضُ السَّالِبَةِ الْكُلِّيَّةِ إِنَّمَا هِيَ الْمُوجَبَةُ، كَقَوْلِنَا: لَا شَيْءَ مِنَ الْإِنْسَانِ بِحَيَوَانٍ، وَبَعْضُ الْإِنْسَانِ حَيَوَانٌ."]]},{"id":"is5_5","label":"التَّنَاقُضُ · ٥","segs":[["matn","وَالْمَحْصُورَتَانِ لَا يَتَحَقَّقُ التَّنَاقُضُ بَيْنَهُمَا إِلَّا بَعْدَ اخْتِلَافِهِمَا فِي الْكَمِّيَّةِ؛ لِأَنَّ الْكُلِّيَّتَيْنِ قَدْ تَكْذِبَانِ، كَقَوْلِنَا: كُلُّ إِنْسَانٍ كَاتِبٌ، وَلَا شَيْءَ مِنَ الْإِنْسَانِ بِكَاتِبٍ."]]},{"id":"is5_6","label":"التَّنَاقُضُ · ٦","segs":[["matn","وَالْجُزْئِيَّتَيْنِ قَدْ تَصْدُقَانِ، كَقَوْلِنَا: بَعْضُ الْإِنْسَانِ كَاتِبٌ، وَبَعْضُ الْإِنْسَانِ لَيْسَ بِكَاتِبٍ."]]}]},{"id":"is6","title":"الْعَكْسُ","units":[{"id":"is6_1","label":"الْعَكْسُ · ١","segs":[["matn","هُوَ أَنْ يَصِيرَ الْمَوْضُوعُ مَحْمُولًا، وَالْمَحْمُولُ مَوْضُوعًا، مَعَ بَقَاءِ السَّلْبِ وَالْإِيجَابِ بِحَالِهِ، وَالتَّصْدِيقِ وَالتَّكْذِيبِ بِحَالِهِ."]]},{"id":"is6_2","label":"الْعَكْسُ · ٢","segs":[["matn","وَالْمُوجَبَةُ الْكُلِّيَّةُ لَا تَنْعَكِسُ كُلِّيَّةً؛ إِذْ يَصْدُقُ قَوْلُنَا: كُلُّ إِنْسَانٍ حَيَوَانٌ، وَلَا يَصْدُقُ: كُلُّ حَيَوَانٍ إِنْسَانٌ."]]},{"id":"is6_3","label":"الْعَكْسُ · ٣","segs":[["matn","بَلْ تَنْعَكِسُ جُزْئِيَّةً؛ لِأَنَّا إِذَا قُلْنَا: كُلُّ إِنْسَانٍ حَيَوَانٌ، يَصْدُقُ: بَعْضُ الْحَيَوَانِ إِنْسَانٌ، فَإِنَّا نَجِدُ شَيْئًا مَوْصُوفًا بِالْإِنْسَانِ وَالْحَيَوَانِ، فَيَكُونُ بَعْضُ الْحَيَوَانِ إِنْسَانًا. وَالْمُوجَبَةُ الْجُزْئِيَّةُ أَيْضًا تَنْعَكِسُ جُزْئِيَّةً بِهَذِهِ الْحُجَّةِ."]]},{"id":"is6_4","label":"الْعَكْسُ · ٤","segs":[["matn","وَالسَّالِبَةُ الْكُلِّيَّةُ تَنْعَكِسُ سَالِبَةً كُلِّيَّةً، وَذَلِكَ بَيِّنٌ بِنَفْسِهِ؛ لِأَنَّهُ إِذَا صَدَقَ: لَا شَيْءَ مِنَ الْإِنْسَانِ بِحَجَرٍ، صَدَقَ: لَا شَيْءَ مِنَ الْحَجَرِ بِإِنْسَانٍ."]]},{"id":"is6_5","label":"الْعَكْسُ · ٥","segs":[["matn","وَالسَّالِبَةُ الْجُزْئِيَّةُ لَا عَكْسَ لَهَا لُزُومًا؛ فَإِنَّهُ يَصْدُقُ: بَعْضُ الْحَيَوَانِ لَيْسَ بِإِنْسَانٍ، وَلَا يَصْدُقُ عَكْسُهُ."]]}]},{"id":"is7","title":"الْقِيَاسُ","units":[{"id":"is7_1","label":"الْقِيَاسُ · ١","segs":[["matn","هُوَ قَوْلٌ مَلْفُوظٌ أَوْ مَعْقُولٌ مُؤَلَّفٌ مِنْ أَقْوَالٍ مَتَى سُلِّمَتْ لَزِمَ عَنْهَا لِذَاتِهَا قَوْلٌ آخَرُ."]]},{"id":"is7_2","label":"الْقِيَاسُ · ٢","segs":[["matn","وَهُوَ إِمَّا اقْتِرَانِيٌّ، كَقَوْلِنَا: كُلُّ جِسْمٍ مُؤَلَّفٌ، وَكُلُّ مُؤَلَّفٍ حَادِثٌ، فَكُلُّ جِسْمٍ حَادِثٌ."]]},{"id":"is7_3","label":"الْقِيَاسُ · ٣","segs":[["matn","وَإِمَّا اسْتِثْنَائِيٌّ، كَقَوْلِنَا: إِنْ كَانَتِ الشَّمْسُ طَالِعَةً فَالنَّهَارُ مَوْجُودٌ، لَكِنِ النَّهَارُ لَيْسَ بِمَوْجُودٍ، فَالشَّمْسُ لَيْسَتْ بِطَالِعَةٍ."]]},{"id":"is7_4","label":"الْقِيَاسُ · ٤","segs":[["matn","وَالْمُكَرَّرُ بَيْنَ مُقَدِّمَتَيِ الْقِيَاسِ يُسَمَّى حَدًّا أَوْسَطَ، وَمَوْضُوعُ الْمَطْلُوبِ يُسَمَّى حَدًّا أَصْغَرَ، وَمَحْمُولُهُ يُسَمَّى حَدًّا أَكْبَرَ."]]},{"id":"is7_5","label":"الْقِيَاسُ · ٥","segs":[["matn","وَالْمُقَدِّمَةُ الَّتِي فِيهَا الْأَصْغَرُ تُسَمَّى صُغْرَى، وَالَّتِي فِيهَا الْأَكْبَرُ تُسَمَّى كُبْرَى، وَهَيْئَةُ التَّأْلِيفِ تُسَمَّى شَكْلًا."]]},{"id":"is7_6","label":"الْقِيَاسُ · ٦","segs":[["matn","وَالْأَشْكَالُ أَرْبَعَةٌ؛ لِأَنَّ الْحَدَّ الْأَوْسَطَ إِنْ كَانَ مَحْمُولًا فِي الصُّغْرَى مَوْضُوعًا فِي الْكُبْرَى فَهُوَ الشَّكْلُ الْأَوَّلُ، وَإِنْ كَانَ بِالْعَكْسِ فَهُوَ الرَّابِعُ، وَإِنْ كَانَ مَوْضُوعًا فِيهِمَا فَهُوَ الثَّالِثُ، وَإِنْ كَانَ مَحْمُولًا فِيهِمَا فَهُوَ الثَّانِي."]]},{"id":"is7_7","label":"الْقِيَاسُ · ٧","segs":[["matn","وَالشَّكْلُ الثَّانِي مِنْهَا يَرْتَدُّ إِلَى الْأَوَّلِ بِعَكْسِ الْكُبْرَى، وَالثَّالِثُ يَرْتَدُّ إِلَيْهِ بِعَكْسِ الصُّغْرَى، وَالرَّابِعُ يَرْتَدُّ إِلَيْهِ بِعَكْسِ التَّرْتِيبِ أَوْ بِعَكْسِ الْمُقَدِّمَتَيْنِ جَمِيعًا."]]},{"id":"is7_8","label":"الْقِيَاسُ · ٨","segs":[["matn","وَالْكَامِلُ الْبَيِّنُ الْإِنْتَاجِ هُوَ الْأَوَّلُ، وَالشَّكْلُ الرَّابِعُ مِنْهَا بَعِيدٌ عَنِ الطَّبْعِ جِدًّا."]]},{"id":"is7_9","label":"الْقِيَاسُ · ٩","segs":[["matn","وَالَّذِي لَهُ طَبْعٌ مُسْتَقِيمٌ وَعَقْلٌ سَلِيمٌ لَا يَحْتَاجُ إِلَى رَدِّ الثَّانِي إِلَى الْأَوَّلِ، وَإِنَّمَا يُنْتِجُ الثَّانِي عِنْدَ اخْتِلَافِ مُقَدِّمَتَيْهِ بِالْإِيجَابِ وَالسَّلْبِ."]]},{"id":"is7_10","label":"الْقِيَاسُ · ١٠","segs":[["matn","وَالشَّكْلُ الْأَوَّلُ هُوَ الَّذِي جُعِلَ مِعْيَارًا لِلْعُلُومِ، فَنُورِدُهُ لِيُجْعَلَ دُسْتُورًا، وَلِيُسْتَنْتَجَ مِنْهُ الْمَطَالِبُ كُلُّهَا."]]},{"id":"is7_11","label":"الْقِيَاسُ · ١١","segs":[["matn","وَشَرْطُ إِنْتَاجِهِ إِيجَابُ الصُّغْرَى وَكُلِّيَّةُ الْكُبْرَى، وَضُرُوبُهُ الْمُنْتِجَةُ أَرْبَعَةٌ:"]]},{"id":"is7_12","label":"الْقِيَاسُ · ١٢","segs":[["matn","الضَّرْبُ الْأَوَّلُ: كُلُّ جِسْمٍ مُؤَلَّفٌ، وَكُلُّ مُؤَلَّفٍ مُحْدَثٌ، فَكُلُّ جِسْمٍ مُحْدَثٌ. الثَّانِي: كُلُّ جِسْمٍ مُؤَلَّفٌ، وَلَا شَيْءَ مِنَ الْمُؤَلَّفِ بِقَدِيمٍ، فَلَا شَيْءَ مِنَ الْجِسْمِ بِقَدِيمٍ."]]},{"id":"is7_13","label":"الْقِيَاسُ · ١٣","segs":[["matn","الثَّالِثُ: بَعْضُ الْجِسْمِ مُؤَلَّفٌ، وَكُلُّ مُؤَلَّفٍ حَادِثٌ، فَبَعْضُ الْجِسْمِ حَادِثٌ. الرَّابِعُ: بَعْضُ الْجِسْمِ مُؤَلَّفٌ، وَلَا شَيْءَ مِنَ الْمُؤَلَّفِ بِقَدِيمٍ، فَبَعْضُ الْجِسْمِ لَيْسَ بِقَدِيمٍ."]]},{"id":"is7_14","label":"الْقِيَاسُ · ١٤","segs":[["matn","وَالْقِيَاسُ الِاقْتِرَانِيُّ: إِمَّا أَنْ يَتَرَكَّبَ مِنْ حَمْلِيَّتَيْنِ كَمَا مَرَّ، وَإِمَّا مِنْ مُتَّصِلَتَيْنِ، كَقَوْلِنَا: إِنْ كَانَتِ الشَّمْسُ طَالِعَةً فَالنَّهَارُ مَوْجُودٌ، وَكُلَّمَا كَانَ النَّهَارُ مَوْجُودًا فَالْأَرْضُ مُضِيئَةٌ، يُنْتِجُ: إِنْ كَانَتِ الشَّمْسُ طَالِعَةً فَالْأَرْضُ مُضِيئَةٌ."]]},{"id":"is7_15","label":"الْقِيَاسُ · ١٥","segs":[["matn","وَإِمَّا مُرَكَّبٌ مِنْ مُنْفَصِلَتَيْنِ، كَقَوْلِنَا: كُلُّ عَدَدٍ إِمَّا زَوْجٌ أَوْ فَرْدٌ، وَكُلُّ زَوْجٍ فَهُوَ إِمَّا زَوْجُ الزَّوْجِ أَوْ زَوْجُ الْفَرْدِ، يُنْتِجُ: كُلُّ عَدَدٍ إِمَّا فَرْدٌ أَوْ زَوْجُ الزَّوْجِ أَوْ زَوْجُ الْفَرْدِ."]]},{"id":"is7_16","label":"الْقِيَاسُ · ١٦","segs":[["matn","وَإِمَّا مِنْ حَمْلِيَّةٍ وَمُتَّصِلَةٍ، كَقَوْلِنَا: كُلَّمَا كَانَ هَذَا إِنْسَانًا فَهُوَ حَيَوَانٌ، وَكُلُّ حَيَوَانٍ جِسْمٌ، يُنْتِجُ: كُلَّمَا كَانَ هَذَا إِنْسَانًا فَهُوَ جِسْمٌ."]]},{"id":"is7_17","label":"الْقِيَاسُ · ١٧","segs":[["matn","وَإِمَّا مِنْ حَمْلِيَّةٍ وَمُنْفَصِلَةٍ، كَقَوْلِنَا: كُلُّ عَدَدٍ إِمَّا زَوْجٌ أَوْ فَرْدٌ، وَكُلُّ زَوْجٍ فَهُوَ مُنْقَسِمٌ بِمُتَسَاوِيَيْنِ، يُنْتِجُ: كُلُّ عَدَدٍ هُوَ إِمَّا فَرْدٌ أَوْ مُنْقَسِمٌ بِمُتَسَاوِيَيْنِ."]]},{"id":"is7_18","label":"الْقِيَاسُ · ١٨","segs":[["matn","وَإِمَّا مِنْ مُتَّصِلَةٍ وَمُنْفَصِلَةٍ، كَقَوْلِنَا: كُلَّمَا كَانَ هَذَا إِنْسَانًا فَهُوَ حَيَوَانٌ، وَكُلُّ حَيَوَانٍ إِمَّا أَبْيَضُ أَوْ أَسْوَدُ، يُنْتِجُ: كُلَّمَا كَانَ هَذَا إِنْسَانًا فَهُوَ إِمَّا أَبْيَضُ أَوْ أَسْوَدُ."]]},{"id":"is7_19","label":"الْقِيَاسُ · ١٩","segs":[["matn","وَأَمَّا الْقِيَاسُ الِاسْتِثْنَائِيُّ فَالشَّرْطِيَّةُ الْمَوْضُوعَةُ فِيهِ إِذَا كَانَتْ مُتَّصِلَةً فَاسْتِثْنَاءُ عَيْنِ الْمُقَدَّمِ يُنْتِجُ عَيْنَ التَّالِي، كَقَوْلِنَا: إِنْ كَانَ هَذَا إِنْسَانًا فَهُوَ حَيَوَانٌ، لَكِنَّهُ إِنْسَانٌ، فَهُوَ حَيَوَانٌ."]]},{"id":"is7_20","label":"الْقِيَاسُ · ٢٠","segs":[["matn","وَاسْتِثْنَاءُ نَقِيضِ التَّالِي يُنْتِجُ نَقِيضَ الْمُقَدَّمِ، كَقَوْلِنَا: إِنْ كَانَ هَذَا الشَّيْءُ إِنْسَانًا فَهُوَ حَيَوَانٌ، لَكِنَّهُ لَيْسَ بِحَيَوَانٍ، فَلَا يَكُونُ إِنْسَانًا."]]},{"id":"is7_21","label":"الْقِيَاسُ · ٢١","segs":[["matn","وَإِنْ كَانَتْ مُنْفَصِلَةً حَقِيقِيَّةً فَاسْتِثْنَاءُ عَيْنِ أَحَدِ الْجُزْءَيْنِ يُنْتِجُ نَقِيضَ الْجُزْءِ الثَّانِي، كَقَوْلِنَا: الْعَدَدُ إِمَّا زَوْجٌ أَوْ فَرْدٌ، لَكِنَّهُ زَوْجٌ، يُنْتِجُ أَنَّهُ لَيْسَ بِفَرْدٍ، أَوْ لَكِنَّهُ فَرْدٌ، يُنْتِجُ أَنَّهُ لَيْسَ زَوْجًا. وَاسْتِثْنَاءُ نَقِيضِ أَحَدِهِمَا يُنْتِجُ عَيْنَ الثَّانِي."]]}]},{"id":"is8","title":"الْبُرْهَانُ","units":[{"id":"is8_1","label":"الْبُرْهَانُ · ١","segs":[["matn","هُوَ قِيَاسٌ مُؤَلَّفٌ مِنْ مُقَدِّمَاتٍ يَقِينِيَّةٍ لِإِنْتَاجِ الْيَقِينِيَّاتِ."]]},{"id":"is8_2","label":"الْبُرْهَانُ · ٢","segs":[["matn","وَالْيَقِينِيَّاتُ سِتَّةُ أَقْسَامٍ: أَحَدُهَا أَوَّلِيَّاتٌ، كَقَوْلِنَا: الْوَاحِدُ نِصْفُ الِاثْنَيْنِ، وَالْكُلُّ أَعْظَمُ مِنَ الْجُزْءِ. وَمُشَاهَدَاتٌ، كَقَوْلِنَا: الشَّمْسُ مُشْرِقَةٌ، وَالنَّارُ مُحْرِقَةٌ."]]},{"id":"is8_3","label":"الْبُرْهَانُ · ٣","segs":[["matn","وَمُجَرَّبَاتٌ، كَقَوْلِنَا: السَّقَمُونِيَا مُسَهِّلَةٌ لِلصَّفْرَاءِ. وَحَدْسِيَّاتٌ، كَقَوْلِنَا: نُورُ الْقَمَرِ مُسْتَفَادٌ مِنْ نُورِ الشَّمْسِ."]]},{"id":"is8_4","label":"الْبُرْهَانُ · ٤","segs":[["matn","وَمُتَوَاتِرَاتٌ، كَقَوْلِنَا: مُحَمَّدٌ ﷺ ادَّعَى النُّبُوَّةَ، وَظَهَرَتِ الْمُعْجِزَةُ عَلَى يَدِهِ."]]},{"id":"is8_5","label":"الْبُرْهَانُ · ٥","segs":[["matn","وَقَضَايَا قِيَاسَاتُهَا مَعَهَا، كَقَوْلِنَا: الْأَرْبَعَةُ زَوْجٌ، بِسَبَبِ وَسَطٍ حَاضِرٍ فِي الذِّهْنِ، وَهُوَ الِانْقِسَامُ بِمُتَسَاوِيَيْنِ."]]},{"id":"is8_6","label":"الْبُرْهَانُ · ٦","segs":[["matn","وَالْجَدَلُ: وَهُوَ قِيَاسٌ مُؤَلَّفٌ مِنْ مُقَدِّمَاتٍ مَشْهُورَةٍ أَوْ مُسَلَّمَةٍ عِنْدَ النَّاسِ أَوْ عِنْدَ الْخَصْمَيْنِ، كَقَوْلِنَا: الْعَدْلُ حَسَنٌ، وَالظُّلْمُ قَبِيحٌ."]]},{"id":"is8_7","label":"الْبُرْهَانُ · ٧","segs":[["matn","وَالْخَطَابَةُ: وَهِيَ قِيَاسٌ مُؤَلَّفٌ مِنْ مُقَدِّمَاتٍ مَقْبُولَةٍ مِنْ شَخْصٍ مُعْتَقَدٍ فِيهِ، أَوْ مَظْنُونَةٍ."]]},{"id":"is8_8","label":"الْبُرْهَانُ · ٨","segs":[["matn","وَالشِّعْرُ: وَهُوَ قِيَاسٌ مُؤَلَّفٌ مِنْ مُقَدِّمَاتٍ مُتَخَيَّلَةٍ تَنْبَسِطُ مِنْهَا النَّفْسُ أَوْ تَنْقَبِضُ."]]},{"id":"is8_9","label":"الْبُرْهَانُ · ٩","segs":[["matn","وَالْمُغَالَطَةُ: وَهِيَ قِيَاسٌ مُؤَلَّفٌ مِنْ مُقَدِّمَاتٍ كَاذِبَةٍ شَبِيهَةٍ بِالْحَقِّ أَوْ بِالْمَشْهُورِ، أَوْ مِنْ مُقَدِّمَاتٍ وَهْمِيَّةٍ كَاذِبَةٍ. وَالْعُمْدَةُ هُوَ الْبُرْهَانُ لَا غَيْرُ."]]}]}],"basmala":"بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ","sharh":false};
